'use client';
import {useEffect,useRef,useState} from 'react';
import {hotelRpc,usd} from '@/lib/pilot';
import {readBillingCheckoutReview} from '@/lib/billing-checkout-review';
import {checkoutRetirementArgs,validateCheckoutRetirement,checkoutArgs,validateCheckoutRequest,validateCheckoutReceipt,readCheckoutStatus,type CheckoutRequest} from '@/lib/billing-checkout-request';
// A timeout leaves the command identity intact: the server may already have saved it.
async function checkoutResponse<T>(request:Promise<T>):Promise<T>{
 let timer:ReturnType<typeof setTimeout>|undefined;
 try{return await Promise.race([request,new Promise<never>((_,reject)=>{timer=setTimeout(()=>reject(Error('Checkout response took too long. Keep the saved request and check its result before retrying.')),30000)})])}
 finally{clearTimeout(timer)}
}
type Props={settledOnly?:boolean;onBusyChange?:(busy:boolean)=>void;actor:string;tenant:string;property:string;reservation:string;review:unknown;onSaved:()=>void};
export function BillingCheckoutConfirm(props:Props){return <Confirm key={[props.actor,props.tenant,props.property,props.reservation].join('/')} {...props}/>}
function Confirm({settledOnly=false,actor,tenant,property,reservation,review,onSaved,onBusyChange}:Props){
 const scope={tenant,property,reservation},key=['irp-checkout',actor,tenant,property,reservation].join('/');
 const [initial]=useState(()=>{try{const raw=sessionStorage.getItem(key);if(!raw)return {pending:null,error:'',cancellation:''};const parsed=JSON.parse(raw);const value:unknown=parsed?.checkout??parsed;validateCheckoutRequest(value,scope,actor);const cancellation=parsed?.checkout?parsed.cancellationReason:'';if(parsed?.checkout){if(Object.keys(parsed).sort().join(',')!=='cancellationReason,checkout')throw Error('Invalid cancellation');checkoutRetirementArgs(value,cancellation)}return {pending:value,error:'',cancellation}}catch{return {pending:null,error:'Saved checkout could not be read. Resolve browser storage before continuing.'}}});
 const [pending,setPending]=useState<CheckoutRequest|null>(initial.pending),[reason,setReason]=useState(''),[confirmed,setConfirmed]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState(initial.error),[notice,setNotice]=useState(''),[done,setDone]=useState(false);
 const [cancelReason,setCancelReason]=useState(''),[cancellation,setCancellation]=useState<string>(initial.cancellation??'');
 const stored=useRef<string|null|undefined>(undefined);
 if(stored.current===undefined){try{stored.current=sessionStorage.getItem(key)}catch{stored.current=null}}
 function preserve(value:string){if(sessionStorage.getItem(key)!==stored.current)throw Error('Saved checkout changed. Reopen checkout to recover the current request.');sessionStorage.setItem(key,value);stored.current=value}
 function clearSaved(){if(sessionStorage.getItem(key)!==stored.current)throw Error('Saved checkout changed. Keep the current recovery request.');sessionStorage.removeItem(key);stored.current=null}
 const alive=useRef(false),lock=useRef(false);useEffect(()=>{alive.current=true;return()=>{alive.current=false}},[]);
 useEffect(()=>{onBusyChange?.(busy);return()=>onBusyChange?.(false)},[busy,onBusyChange]);
 useEffect(()=>{if(!pending)setConfirmed(false)},[review,pending]);
 let summary:ReturnType<typeof readBillingCheckoutReview>|null=null;try{summary=readBillingCheckoutReview(pending?.review??review,scope)}catch{}
 async function run(checkOnly:boolean){if(lock.current||initial.error||done||(!checkOnly&&(!!cancellation||(settledOnly&&summary?.disposition!=="zero")))||(!pending&&!confirmed))return;lock.current=true;setBusy(true);setError('');setNotice('');let sent=false;
 try{const request:CheckoutRequest=pending??{version:1,actor,...scope,request:crypto.randomUUID(),review,reason:reason.trim()||(summary?.disposition==='zero'?'Guest balance settled':'')};validateCheckoutRequest(request,scope,actor);preserve(JSON.stringify(cancellation?{checkout:request,cancellationReason:cancellation}:request));setPending(request);
 sent=true;const result=checkOnly?readCheckoutStatus(await checkoutResponse(hotelRpc('billing_checkout_status',{p_tenant:tenant,p_property:property,p_request:request.request})),request):validateCheckoutReceipt(await checkoutResponse(hotelRpc('save_billing_checkout',checkoutArgs(request))),request);
 if(!alive.current)return;if(!result){setNotice('No saved checkout found. Keep this request and retry the same checkout.');return}
 clearSaved();setPending(null);setDone(true);setNotice('Checkout confirmed. No payment was collected.');onSaved();
 }catch(e){if(alive.current)setError(sent?'Checkout could not be confirmed. The saved request is retained; check its result or retry.':e instanceof Error?e.message:'Unable to preserve checkout request.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 async function cancel(){if(lock.current||!pending||initial.error||done)return;lock.current=true;setBusy(true);setError('');try{const reason=cancellation||cancelReason.trim();const args=checkoutRetirementArgs(pending,reason);preserve(JSON.stringify({checkout:pending,cancellationReason:reason}));setCancellation(reason);const result=await checkoutResponse(hotelRpc('retire_billing_checkout',args));validateCheckoutRetirement(result,pending,reason);if(!alive.current)return;clearSaved();setPending(null);setDone(true);setNotice('Unsaved checkout cancelled. Reopen checkout to prepare a fresh review.')}catch(e){if(alive.current)setError(e instanceof Error?e.message:'Cancellation could not be confirmed. Retry the saved cancellation.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 return <section aria-label="Confirm checkout"><h3>Confirm checkout</h3>{error&&<p role="alert">{error}</p>}{notice&&<p role="status">{notice}</p>}{!done&&<>{summary?.balance.available&&<p>Guest {summary.disposition==='credit'?'credit':'balance'}: {usd(Math.abs(Number(summary.balance.guestMinor)))} · Transferred: {usd(Number(summary.balance.transferredMinor))}</p>}{settledOnly&&summary&&summary.disposition!=="zero"&&<p>A manager must review this balance before checkout.</p>}<p>Checkout does not collect payment, forgive a balance, or issue a refund.</p>{pending?<p>Saved reason: {pending.reason}</p>:<><label className="field">Checkout notes / balance arrangement<textarea value={reason} maxLength={500} disabled={busy} onChange={e=>setReason(e.target.value)}/></label><label><input type="checkbox" checked={confirmed} disabled={busy} onChange={e=>setConfirmed(e.target.checked)}/> I reviewed the guest balance and approve checkout.</label></>}<button disabled={busy||!!cancellation||(settledOnly&&summary?.disposition!=="zero")||!!initial.error||!summary?.eligible||!summary.balance.available||(!pending&&(!confirmed||(summary?.disposition!=="zero"&&reason.trim().length<4)))} onClick={()=>void run(false)}>{pending?'Retry saved checkout':'Confirm checkout'}</button>{pending&&<><button disabled={busy} onClick={()=>void run(true)}>Check checkout result</button><label className="field">Cancellation reason<textarea value={cancellation||cancelReason} disabled={busy||!!cancellation} maxLength={500} onChange={e=>setCancelReason(e.target.value)}/></label><p>Cancel only this unsaved checkout request. A completed checkout remains unchanged.</p><button disabled={busy||(!cancellation&&cancelReason.trim().length<4)} onClick={()=>void cancel()}>{cancellation?'Retry saved cancellation':'Confirm cancellation of unsaved checkout'}</button></>}</>}</section>
}
